#include <bits/stdc++.h>
using namespace std;
int main(){mt19937 rng(123);for(int k=4;k<=7;k++){int d=k+1;vector<vector<int>> ps;vector<int> p(k);iota(p.begin(),p.end(),0);do{ps.push_back(p);}while(next_permutation(p.begin(),p.end()));vector<vector<int>> fs;int q=1;for(int i=0;i<k;i++)q*=3;for(int s=0;s<q;s++){vector<int>c(k);int t=s;for(int &v:c)v=t%3,t/=3;vector<int>f;for(auto &p:ps){int b=0;for(int i:p)if(c[i]){b=c[i]-1;break;}f.push_back(b);}fs.push_back(f);}int best=0;for(int it=0;it<200000;it++){vector<int>ix(d);for(int &v:ix)v=rng()%ps.size();vector<bool>seen(1<<d);int z=0;for(auto &f:fs){int b=0;for(int j=0;j<d;j++)b|=f[ix[j]]<<j;if(!seen[b])seen[b]=true,z++;}if(z>best){best=z;cerr<<k<<" "<<best<<"/"<<(1<<d)<<endl;}if(z==(1<<d)){for(int i:ix){for(int v:ps[i])cout<<v;cout<<" ";}cout<<endl;break;}}}}
